mod bank {
    var balance: Int = 0

    pub fn deposit(amount: Int) {
        balance = balance + amount
    }

    pub fn withdraw(amount: Int) -> Bool {
        if balance >= amount {
            balance = balance - amount
            return true
        }
        return false
    }

    pub fn get_balance() -> Int {
        return balance
    }
}

fn main() {
    bank::deposit(100)
    bank::withdraw(30)
    io.println("Balance: {bank::get_balance()}")
}
